import React from 'react';

export default function Navbar({ onNavigate, onLogout, user }) {

  const scrollToSection = (id) => {
    const el = document.getElementById(id);
    if (el) el.scrollIntoView({ behavior: "smooth" });
  };

  return (
    <nav className="nav">
      <div className="brand" onClick={() => scrollToSection('home-section')}>
        NGO Portal
      </div>

      <div className="links">
        <button onClick={() => scrollToSection('home-section')}>Home</button>
        <button onClick={() => scrollToSection('about-section')}>About Us</button>
        <button onClick={() => scrollToSection('events-section')}>Events</button>

        {!user && <button onClick={() => onNavigate('login')}>Login</button>}
        {!user && <button onClick={() => onNavigate('register')}>Register</button>}

        {user && <button onClick={() => onNavigate('dashboard')}>Dashboard</button>}
        {user && <button onClick={onLogout}>Logout</button>}
      </div>
    </nav>
  );
}
